// NOTE: do NOT mock ../src/agents.ts. installer.installSkillForAgent relies on the
// real `agents` map (e.g. codex.skillsDir / globalSkillsDir); a stubbed map with only
// `displayName` makes getAgentBaseDir() do join(baseDir, undefined) and throws
// "The \"path\" argument must be of type string. Received undefined". We pass
// `agent: ['codex']` to runAdd so the detectInstalledAgents() branch is skipped anyway.

// Keep parseSource/getOwnerRepo real, but stub the only network call (isRepoPrivate)
// so the test runs offline.
vi.mock('../src/source-parser.ts', async (importActual) => {
  const actual = await importActual<typeof import('../src/source-parser.ts')>();
  return {
    ...actual,
    isRepoPrivate: vi.fn().mockResolvedValue(false),
  };
});

// Simulate a GitHub clone without touching the network: cloneRepo returns a local
// fixture directory. cleanupTempDir is a no-op so we control teardown ourselves.
vi.mock('../src/git.ts', () => ({
  cloneRepo: vi.fn(),
  cleanupTempDir: vi.fn().mockResolvedValue(undefined),
}));

import { runAdd } from '../src/add.ts';
import { cloneRepo } from '../src/git.ts';
import * as installer from '../src/installer.ts';

describe('root-level disk install (issue #1603)', () => {
  let base: string;
  let fixture: string; // a fake cloned repo (SKILL.md at the repo root)
  let project: string; // install target cwd
  let origCwd: string;
  let spy: ReturnType<typeof vi.spyOn>;

  beforeEach(async () => {
    base = await mkdtemp(join(tmpdir(), 'root-disk-'));
    fixture = join(base, 'fixture-repo');
    await mkdir(fixture, { recursive: true });
    await writeFile(
      join(fixture, 'SKILL.md'),
      '---\nname: myrootskill\ndescription: root level skill\n---\n',
      'utf-8'
    );
    await mkdir(join(fixture, 'scripts'), { recursive: true });
    await writeFile(join(fixture, 'scripts', 'check-deps.mjs'), 'console.log("x")\n', 'utf-8');
    await mkdir(join(fixture, 'references'), { recursive: true });
    await writeFile(join(fixture, 'references', 'guide.md'), '# guide\n', 'utf-8');

    project = join(base, 'project');
    await mkdir(project, { recursive: true });
    origCwd = process.cwd();
    process.chdir(project);

    // Drive the GitHub-clone code path (tempDir === skill.path) without network.
    vi.mocked(cloneRepo).mockResolvedValue(fixture);

    spy = vi.spyOn(installer, 'installSkillForAgent');
    vi.spyOn(process, 'exit').mockImplementation((() => {
      throw new Error('process.exit called');
    }) as never);
  });

  afterEach(async () => {
    process.chdir(origCwd);
    await rm(base, { recursive: true, force: true });
    vi.restoreAllMocks();
  });

  it('installs the full directory (scripts/ + references/) for a root-level SKILL.md repo', async () => {
    // A github-style source goes through cloneRepo + discoverSkills(tempDir),
    // where skill.path === tempDir. This is exactly the branch that dropped the
    // supporting files before the fix (see issue #1603).
    await runAdd(['someowner/somerepo'], {
      yes: true,
      agent: ['codex'],
      global: false,
      mode: 'copy',
    });

    // The disk-based install path must be used (not the blob single-file path).
    expect(spy).toHaveBeenCalled();

    const installed = join(project, '.agents', 'skills', 'myrootskill');
    await expect(readFile(join(installed, 'SKILL.md'), 'utf-8')).resolves.toContain('myrootskill');
    // Regression for #1603: supporting files must NOT be dropped.
    await expect(readFile(join(installed, 'scripts', 'check-deps.mjs'), 'utf-8')).resolves.toBe(
      'console.log("x")\n'
    );
    await expect(readFile(join(installed, 'references', 'guide.md'), 'utf-8')).resolves.toBe(
      '# guide\n'
    );
  });
});

/**
 * Regression tests for symlink installs when canonical and agent paths match.
 */

import { describe, it, expect } from 'vitest';
import {
  mkdtemp,
  mkdir,
  rm,
  writeFile,
  lstat,
  readFile,
  readlink,
  symlink,
  readdir,
} from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { installSkillForAgent, installBlobSkillForAgent } from '../src/installer.ts';

async function makeSkillSource(root: string, name: string): Promise<string> {
  const dir = join(root, 'source-skill');
  await mkdir(dir, { recursive: true });
  const skillMd = `---\nname: ${name}\ndescription: test\n---\n`;
  await writeFile(join(dir, 'SKILL.md'), skillMd, 'utf-8');
  return dir;
}

describe('installer symlink regression', () => {
  it('does not create self-loop when canonical and agent paths match', async () => {
    const root = await mkdtemp(join(tmpdir(), 'add-skill-'));
    const projectDir = join(root, 'project');
    await mkdir(projectDir, { recursive: true });

    const skillName = 'self-loop-skill';
    const skillDir = await makeSkillSource(root, skillName);

    try {
      const result = await installSkillForAgent(
        { name: skillName, description: 'test', path: skillDir },
        'amp',
        { cwd: projectDir, mode: 'symlink', global: false }
      );

      expect(result.success).toBe(true);
      expect(result.symlinkFailed).toBeUndefined();

      const installedPath = join(projectDir, '.agents/skills', skillName);
      const stats = await lstat(installedPath);
      expect(stats.isSymbolicLink()).toBe(false);
      expect(stats.isDirectory()).toBe(true);

      const contents = await readFile(join(installedPath, 'SKILL.md'), 'utf-8');
      expect(contents).toContain(`name: ${skillName}`);
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });

  it('skips agent installs that would overwrite the source directory', async () => {
    const root = await mkdtemp(join(tmpdir(), 'add-skill-'));
    const projectDir = join(root, 'project');
    await mkdir(projectDir, { recursive: true });

    const skillName = 'source-overlap-skill';
    const skillDir = join(projectDir, 'skills', skillName);
    await mkdir(skillDir, { recursive: true });
    await writeFile(
      join(skillDir, 'SKILL.md'),
      `---\nname: ${skillName}\ndescription: test\n---\n`,
      'utf-8'
    );
    await writeFile(join(skillDir, 'extra.txt'), 'preserve me\n', 'utf-8');

    try {
      const result = await installSkillForAgent(
        { name: skillName, description: 'test', path: skillDir },
        'openclaw',
        { cwd: projectDir, mode: 'symlink', global: false }
      );

      expect(result.success).toBe(true);
      expect(result.skipped).toBe(true);

      const stats = await lstat(skillDir);
      expect(stats.isDirectory()).toBe(true);
      expect(stats.isSymbolicLink()).toBe(false);
      await expect(readFile(join(skillDir, 'SKILL.md'), 'utf-8')).resolves.toContain(
        `name: ${skillName}`
      );
      await expect(readFile(join(skillDir, 'extra.txt'), 'utf-8')).resolves.toBe('preserve me\n');
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });

  it('cleans pre-existing self-loop symlink in canonical dir', async () => {
    const root = await mkdtemp(join(tmpdir(), 'add-skill-'));
    const projectDir = join(root, 'project');
    await mkdir(projectDir, { recursive: true });

    const skillName = 'self-loop-skill';
    const skillDir = await makeSkillSource(root, skillName);
    const canonicalDir = join(projectDir, '.agents/skills', skillName);

    try {
      await mkdir(join(projectDir, '.agents/skills'), { recursive: true });
      await symlink(skillName, canonicalDir);
      const preStats = await lstat(canonicalDir);
      expect(preStats.isSymbolicLink()).toBe(true);

      const result = await installSkillForAgent(
        { name: skillName, description: 'test', path: skillDir },
        'amp',
        { cwd: projectDir, mode: 'symlink', global: false }
      );

      expect(result.success).toBe(true);

      const postStats = await lstat(canonicalDir);
      expect(postStats.isSymbolicLink()).toBe(false);
      expect(postStats.isDirectory()).toBe(true);
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });

  // Regression test for #293: when agent skills dir is a symlink to canonical dir
  it('handles agent skills dir being a symlink to canonical dir', async () => {
    const root = await mkdtemp(join(tmpdir(), 'add-skill-'));
    const projectDir = join(root, 'project');
    await mkdir(projectDir, { recursive: true });

    const skillName = 'symlinked-dir-skill';
    const skillDir = await makeSkillSource(root, skillName);

    // Create canonical dir: .agents/skills
    const canonicalBase = join(projectDir, '.agents', 'skills');
    await mkdir(canonicalBase, { recursive: true });

    // Create .claude directory and symlink .claude/skills -> .agents/skills
    const claudeDir = join(projectDir, '.claude');
    await mkdir(claudeDir, { recursive: true });
    const claudeSkillsDir = join(claudeDir, 'skills');
    await symlink(canonicalBase, claudeSkillsDir);

    try {
      // Install for claude-code, which has skillsDir: '.claude/skills'
      const result = await installSkillForAgent(
        { name: skillName, description: 'test', path: skillDir },
        'claude-code',
        { cwd: projectDir, mode: 'symlink', global: false }
      );

      expect(result.success).toBe(true);
      expect(result.symlinkFailed).toBeUndefined();

      // The skill should exist in the canonical location
      const canonicalSkillDir = join(canonicalBase, skillName);
      const stats = await lstat(canonicalSkillDir);
      expect(stats.isDirectory()).toBe(true);

      // It should NOT be a broken symlink - it should be a real directory
      const contents = await readFile(join(canonicalSkillDir, 'SKILL.md'), 'utf-8');
      expect(contents).toContain(`name: ${skillName}`);

      // The skill should also be accessible via the symlinked path
      const claudeSkillDir = join(claudeSkillsDir, skillName);
      const claudeContents = await readFile(join(claudeSkillDir, 'SKILL.md'), 'utf-8');
      expect(claudeContents).toContain(`name: ${skillName}`);

      // There should be no broken symlinks in canonical dir
      const canonicalEntries = await readdir(canonicalBase, { withFileTypes: true });
      for (const entry of canonicalEntries) {
        if (entry.name === skillName) {
          const entryPath = join(canonicalBase, entry.name);
          const entryStats = await lstat(entryPath);
          // Should be a real directory, not a symlink
          expect(entryStats.isDirectory()).toBe(true);
        }
      }
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });

  it('creates project-local Claude Code symlinks when .claude does not exist', async () => {
    const root = await mkdtemp(join(tmpdir(), 'add-skill-'));
    const projectDir = join(root, 'project');
    await mkdir(projectDir, { recursive: true });

    const skillName = 'fresh-claude-project-skill';
    const skillDir = await makeSkillSource(root, skillName);

    try {
      const result = await installSkillForAgent(
        { name: skillName, description: 'test', path: skillDir },
        'claude-code',
        { cwd: projectDir, mode: 'symlink', global: false }
      );

      expect(result.success).toBe(true);
      expect(result.skipped).toBeUndefined();
      expect(result.symlinkFailed).toBeUndefined();

      const canonicalSkillDir = join(projectDir, '.agents/skills', skillName);
      const claudeSkillDir = join(projectDir, '.claude/skills', skillName);

      expect((await lstat(canonicalSkillDir)).isDirectory()).toBe(true);
      expect((await lstat(claudeSkillDir)).isSymbolicLink()).toBe(true);

      const contents = await readFile(join(claudeSkillDir, 'SKILL.md'), 'utf-8');
      expect(contents).toContain(`name: ${skillName}`);
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });

  // Regression test for #1607: same claude-code exemption as installSkillForAgent,
  // but for the blob install path (used by `skills add <owner>/<repo>`).
  it('creates project-local Claude Code symlinks for blob installs when .claude does not exist', async () => {
    const root = await mkdtemp(join(tmpdir(), 'add-skill-'));
    const projectDir = join(root, 'project');
    await mkdir(projectDir, { recursive: true });

    const skillName = 'fresh-claude-blob-skill';

    try {
      const result = await installBlobSkillForAgent(
        {
          installName: skillName,
          files: [
            {
              path: 'SKILL.md',
              contents: `---\nname: ${skillName}\ndescription: test\n---\n`,
            },
          ],
        },
        'claude-code',
        { cwd: projectDir, mode: 'symlink', global: false }
      );

      expect(result.success).toBe(true);
      expect(result.skipped).toBeUndefined();
      expect(result.symlinkFailed).toBeUndefined();

      const canonicalSkillDir = join(projectDir, '.agents/skills', skillName);
      const claudeSkillDir = join(projectDir, '.claude/skills', skillName);

      expect((await lstat(canonicalSkillDir)).isDirectory()).toBe(true);
      expect((await lstat(claudeSkillDir)).isSymbolicLink()).toBe(true);

      const contents = await readFile(join(claudeSkillDir, 'SKILL.md'), 'utf-8');
      expect(contents).toContain(`name: ${skillName}`);
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });

  it('creates a blob symlink when the caller allows the missing agent root', async () => {
    const root = await mkdtemp(join(tmpdir(), 'add-skill-'));
    const projectDir = join(root, 'project');
    await mkdir(projectDir, { recursive: true });

    const skillName = 'explicit-kiro-blob-skill';

    try {
      const result = await installBlobSkillForAgent(
        {
          installName: skillName,
          files: [
            {
              path: 'SKILL.md',
              contents: `---\nname: ${skillName}\ndescription: test\n---\n`,
            },
          ],
        },
        'kiro-cli',
        {
          cwd: projectDir,
          mode: 'symlink',
          global: false,
          createMissingAgentRoot: true,
        }
      );

      expect(result.success).toBe(true);
      expect(result.skipped).toBeUndefined();
      expect((await lstat(join(projectDir, '.kiro/skills', skillName))).isSymbolicLink()).toBe(
        true
      );
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });

  // Regression test for #294: universal-only global install should not create agent-specific symlinks
  it('does not create agent-specific symlinks for universal agents on global install', async () => {
    const root = await mkdtemp(join(tmpdir(), 'add-skill-'));

    const skillName = 'universal-only-skill';
    const skillDir = await makeSkillSource(root, skillName);

    // We test with 'github-copilot', a universal agent (skillsDir: '.agents/skills')
    // whose globalSkillsDir is different from canonical (~/.copilot/skills vs ~/.agents/skills)
    // For testing, we use a project-level install to avoid writing to actual home dir.
    // But the bug only manifests with global: true.
    // We can't safely test with global: true in unit tests (it would write to ~/.copilot/skills).
    // Instead, we verify that the installSkillForAgent function returns the canonical path
    // as both path and canonicalPath for universal agents with global install.

    // For a project-level install, universal agents have matching canonical and agent dirs,
    // so we just verify the function works correctly.
    const projectDir = join(root, 'project');
    await mkdir(projectDir, { recursive: true });

    try {
      const result = await installSkillForAgent(
        { name: skillName, description: 'test', path: skillDir },
        'github-copilot', // Universal agent
        { cwd: projectDir, mode: 'symlink', global: false }
      );

      expect(result.success).toBe(true);
      expect(result.symlinkFailed).toBeUndefined();

      // For a project-level universal agent, canonical and agent dir are the same
      // (.agents/skills), so no symlink should be created
      const installedPath = join(projectDir, '.agents/skills', skillName);
      const stats = await lstat(installedPath);
      expect(stats.isDirectory()).toBe(true);
      expect(stats.isSymbolicLink()).toBe(false);
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  });
});

import { describe, it, expect, beforeAll, beforeEach, afterEach, afterAll, vi } from 'vitest';
import { mkdir, mkdtemp, writeFile, rm, symlink } from 'fs/promises';
import { join } from 'path';
import { tmpdir } from 'os';
import { createTestHomeEnvironment } from '../src/test-utils.ts';

let listInstalledSkills: typeof import('../src/installer.ts').listInstalledSkills;
let agentsModule: typeof import('../src/agents.ts');

describe('listInstalledSkills', () => {
  let testDir: string;
  let testHome: string;

  beforeAll(async () => {
    testHome = await mkdtemp(join(tmpdir(), 'skills-list-installed-home-'));

    for (const [name, value] of Object.entries(createTestHomeEnvironment(testHome))) {
      vi.stubEnv(name, value);
    }

    vi.resetModules();
    agentsModule = await import('../src/agents.ts');
    ({ listInstalledSkills } = await import('../src/installer.ts'));
  });

  beforeEach(async () => {
    testDir = join(tmpdir(), `add-skill-test-${Date.now()}-${Math.random().toString(36).slice(2)}`);
    await mkdir(testDir, { recursive: true });
  });

  afterEach(async () => {
    vi.restoreAllMocks();
    await rm(testDir, { recursive: true, force: true });
  });

  afterAll(async () => {
    vi.unstubAllEnvs();
    await rm(testHome, { recursive: true, force: true });
  });

  // Helper to create a skill directory with SKILL.md
  async function createSkillDir(
    basePath: string,
    skillName: string,
    skillData: { name: string; description: string }
  ): Promise<string> {
    const skillDir = join(basePath, '.agents', 'skills', skillName);
    await mkdir(skillDir, { recursive: true });
    const skillMdContent = `---
name: ${skillData.name}
description: ${skillData.description}
---

# ${skillData.name}

${skillData.description}
`;
    await writeFile(join(skillDir, 'SKILL.md'), skillMdContent);
    return skillDir;
  }

  it('should return empty array for empty directory', async () => {
    const skills = await listInstalledSkills({ global: false, cwd: testDir });
    expect(skills).toEqual([]);
  });

  it('should find single skill in project directory', async () => {
