import { describe, expect, it } from 'vitest';
import pc from 'picocolors';
import {
  approxStringWidth,
  buildSearchEntries,
  countVisualRowsForLines,
  formatDetailLines,
  getSelectAllState,
  toggleAllItems,
  toggleSearchEntry,
  visualRowsForLine,
} from '../src/prompts/search-multiselect.ts';

describe('searchMultiselect visual row counting', () => {
  it('counts ASCII width as one column per character', () => {
    expect(approxStringWidth('abc')).toBe(3);
    expect(approxStringWidth('a'.repeat(160))).toBe(160);
  });

  it('treats common CJK as double-width', () => {
    expect(approxStringWidth('中')).toBe(2);
    expect(approxStringWidth('中文')).toBe(4);
  });

  it('computes wrap rows for long ASCII lines', () => {
    const line = 'x'.repeat(160);
    expect(visualRowsForLine(line, 80)).toBe(2);
    expect(visualRowsForLine(line, 40)).toBe(4);
  });

  it('strips ANSI before measuring so colors do not affect wrap', () => {
    const line = pc.bold('z'.repeat(100));
    expect(visualRowsForLine(line, 80)).toBe(2);
  });

  it('sums logical lines using explicit column width', () => {
    const lines = ['short', 'x'.repeat(160)];
    expect(countVisualRowsForLines(lines, 80)).toBe(1 + 2);
  });

  it('matches prior behavior when each line fits in one row', () => {
    const lines = ['a', 'b', 'c'];
    expect(countVisualRowsForLines(lines, 120)).toBe(3);
  });

  it('reserves a fixed number of detail lines for short descriptions', () => {
    expect(formatDetailLines('One concise description.', 40, 2)).toEqual([
      'One concise description.',
      '',
    ]);
  });

  it('wraps and truncates long descriptions inside the reserved detail pane', () => {
    const lines = formatDetailLines('One two three four five six seven eight nine', 16, 2);

    expect(lines).toHaveLength(2);
    expect(lines[1]).toMatch(/…$/);
    expect(lines.every((line) => approxStringWidth(line) <= 16)).toBe(true);
  });

  it('makes group headings navigable and keeps their member skills together', () => {
    const entries = buildSearchEntries(
      [
        { value: 'review', label: 'code-review', group: 'Mattpocock Skills' },
        { value: 'design', label: 'codebase-design', group: 'Mattpocock Skills' },
        { value: 'qa', label: 'qa', group: 'General' },
      ],
      true
    );

    expect(entries).toEqual([
      {
        type: 'group',
        group: 'Mattpocock Skills',
        collapsed: false,
        items: [
          { value: 'review', label: 'code-review', group: 'Mattpocock Skills' },
          { value: 'design', label: 'codebase-design', group: 'Mattpocock Skills' },
        ],
      },
      { type: 'item', item: { value: 'review', label: 'code-review', group: 'Mattpocock Skills' } },
      {
        type: 'item',
        item: { value: 'design', label: 'codebase-design', group: 'Mattpocock Skills' },
      },
      {
        type: 'group',
        group: 'General',
        collapsed: false,
        items: [{ value: 'qa', label: 'qa', group: 'General' }],
      },
      { type: 'item', item: { value: 'qa', label: 'qa', group: 'General' } },
    ]);
  });

  it('keeps collapsed groups visible while hiding their child skills', () => {
    const entries = buildSearchEntries(
      [
        { value: 'review', label: 'code-review', group: 'Mattpocock Skills' },
        { value: 'design', label: 'codebase-design', group: 'Mattpocock Skills' },
        { value: 'qa', label: 'qa', group: 'General' },
      ],
      true,
      new Set(['Mattpocock Skills'])
    );

    expect(entries).toHaveLength(3);
    expect(entries[0]).toMatchObject({
      type: 'group',
      group: 'Mattpocock Skills',
      collapsed: true,
    });
    expect(entries[1]).toMatchObject({ type: 'group', group: 'General', collapsed: false });
    expect(entries[2]).toMatchObject({ type: 'item', item: { value: 'qa' } });
  });

  it('selects every skill from a group heading, then clears them on the next toggle', () => {
    const entries = buildSearchEntries(
      [
        { value: 'review', label: 'code-review', group: 'Mattpocock Skills' },
        { value: 'design', label: 'codebase-design', group: 'Mattpocock Skills' },
      ],
      true
    );
    const selected = new Set<string>();

    toggleSearchEntry(selected, entries[0]);
    expect(selected).toEqual(new Set(['review', 'design']));

    toggleSearchEntry(selected, entries[0]);
    expect(selected).toEqual(new Set());
  });

  it('tracks none, partial, and all states as individual skills are selected', () => {
    const items = [
      { value: 'review', label: 'code-review' },
      { value: 'design', label: 'codebase-design' },
    ];
    const selected = new Set<string>();

    expect(getSelectAllState(selected, items)).toBe('none');
    selected.add('review');
    expect(getSelectAllState(selected, items)).toBe('partial');
    selected.add('design');
    expect(getSelectAllState(selected, items)).toBe('all');
  });

  it('selects every skill from Select All, then clears them on the next toggle', () => {
    const items = [
      { value: 'review', label: 'code-review' },
      { value: 'design', label: 'codebase-design' },
    ];
    const selected = new Set<string>();

    toggleAllItems(selected, items);
    expect(selected).toEqual(new Set(['review', 'design']));

    toggleAllItems(selected, items);
    expect(selected).toEqual(new Set());
  });
});

import { describe, expect, it } from 'vitest';
import { access, mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { detectInstalledAgents, getEveSubagents } from '../src/agents.ts';
import {
  getAgentBaseDir,
  getEveSubagentSkillsDir,
  installBlobSkillForAgent,
  installSkillForAgent,
  isSkillInstalled,
  listInstalledSkills,
} from '../src/installer.ts';

async function makeEveProject(): Promise<string> {
  const projectDir = await mkdtemp(join(tmpdir(), 'skills-eve-'));
  await mkdir(join(projectDir, 'agent'), { recursive: true });
  await writeFile(
    join(projectDir, 'package.json'),
    JSON.stringify({ dependencies: { eve: '^0.11.5' } }),
    'utf-8'
  );
  return projectDir;
}

async function addEveSubagent(projectDir: string, name: string): Promise<void> {
  await mkdir(join(projectDir, 'agent', 'subagents', name), { recursive: true });
}

async function makeSourceSkill(name: string): Promise<{ root: string; skillDir: string }> {
  const root = await mkdtemp(join(tmpdir(), 'skills-eve-source-'));
  const skillDir = join(root, name);
  await mkdir(skillDir, { recursive: true });
  await writeFile(
    join(skillDir, 'SKILL.md'),
    `---\nname: ${name}\ndescription: ${name} skill\n---\n# ${name}\n`,
    'utf-8'
  );
  return { root, skillDir };
}

describe('Eve agent support', () => {
  it('detects an Eve project from agent/ and the eve package dependency', async () => {
    const projectDir = await makeEveProject();
    const previousCwd = process.cwd();

    try {
      process.chdir(projectDir);
      await expect(detectInstalledAgents()).resolves.toContain('eve');
    } finally {
      process.chdir(previousCwd);
      await rm(projectDir, { recursive: true, force: true });
    }
  });

  it('installs disk skills to agent/skills without unsupported name frontmatter', async () => {
    const projectDir = await makeEveProject();
    const root = await mkdtemp(join(tmpdir(), 'skills-eve-source-'));
    const skillDir = join(root, 'source-skill');
    await mkdir(skillDir, { recursive: true });
    await writeFile(
      join(skillDir, 'SKILL.md'),
      '---\nname: test-skill\ndescription: Test skill\n---\n# Test\n',
      'utf-8'
    );

    try {
      const result = await installSkillForAgent(
        { name: 'test-skill', description: 'Test skill', path: skillDir },
        'eve',
        { cwd: projectDir, mode: 'symlink', global: false }
      );

      expect(result.success).toBe(true);
      expect(result.path).toBe(join(projectDir, 'agent/skills/test-skill'));
      expect(result.canonicalPath).toBe(join(projectDir, 'agent/skills/test-skill'));

      const installed = await readFile(
        join(projectDir, 'agent/skills/test-skill/SKILL.md'),
        'utf-8'
      );
      expect(installed).toContain('description: Test skill');
      expect(installed).toContain('name: test-skill');
    } finally {
      await rm(projectDir, { recursive: true, force: true });
      await rm(root, { recursive: true, force: true });
    }
  });

  it('installs blob skills without unsupported name frontmatter', async () => {
    const projectDir = await makeEveProject();

    try {
      const result = await installBlobSkillForAgent(
        {
          installName: 'blob-skill',
          files: [
            {
              path: 'SKILL.md',
              contents: '---\nname: blob-skill\ndescription: Blob skill\n---\n# Blob\n',
            },
          ],
        },
        'eve',
        { cwd: projectDir, mode: 'copy', global: false }
      );

      expect(result.success).toBe(true);
      expect(result.path).toBe(join(projectDir, 'agent/skills/blob-skill'));

      const installed = await readFile(
        join(projectDir, 'agent/skills/blob-skill/SKILL.md'),
        'utf-8'
      );
      expect(installed).toContain('description: Blob skill');
      expect(installed).toContain('name: blob-skill');
    } finally {
      await rm(projectDir, { recursive: true, force: true });
    }
  });
});

describe('Eve subagents', () => {
  it('discovers subagent directories under agent/subagents, sorted', async () => {
    const projectDir = await makeEveProject();
    try {
      await addEveSubagent(projectDir, 'writer');
      await addEveSubagent(projectDir, 'research');
      // A stray file should be ignored — only directories are subagents.
      await writeFile(join(projectDir, 'agent', 'subagents', 'notes.txt'), 'x', 'utf-8');

      expect(getEveSubagents(projectDir)).toEqual(['research', 'writer']);
    } finally {
      await rm(projectDir, { recursive: true, force: true });
    }
  });

  it('returns no subagents when agent/subagents is absent', async () => {
    const projectDir = await makeEveProject();
    try {
      expect(getEveSubagents(projectDir)).toEqual([]);
    } finally {
      await rm(projectDir, { recursive: true, force: true });
    }
  });

  it('resolves the base dir to the subagent skills directory', () => {
    const cwd = '/tmp/eve-project';
    expect(getAgentBaseDir('eve', false, cwd, 'research')).toBe(
      join(cwd, 'agent', 'subagents', 'research', 'skills')
    );
    // No subagent → root agent skills dir.
    expect(getAgentBaseDir('eve', false, cwd)).toBe(join(cwd, 'agent', 'skills'));
  });

  it('sanitizes subagent names to prevent path traversal', () => {
    const cwd = '/tmp/eve-project';
    const resolved = getEveSubagentSkillsDir('../../etc', cwd);
    expect(resolved.startsWith(join(cwd, 'agent', 'subagents'))).toBe(true);
    expect(resolved).not.toContain('..');
  });

  it('installs a disk skill into a subagent skills directory', async () => {
    const projectDir = await makeEveProject();
    await addEveSubagent(projectDir, 'research');
    const { root, skillDir } = await makeSourceSkill('subagent-skill');

    try {
      const result = await installSkillForAgent(
        { name: 'subagent-skill', description: 'subagent-skill skill', path: skillDir },
        'eve',
        { cwd: projectDir, mode: 'copy', global: false, eveSubagent: 'research' }
      );

      expect(result.success).toBe(true);
      expect(result.path).toBe(join(projectDir, 'agent/subagents/research/skills/subagent-skill'));

      const installed = await readFile(
        join(projectDir, 'agent/subagents/research/skills/subagent-skill/SKILL.md'),
        'utf-8'
      );
      expect(installed).toContain('description: subagent-skill skill');

      // The root agent dir should be untouched.
      await expect(access(join(projectDir, 'agent/skills/subagent-skill'))).rejects.toBeTruthy();
    } finally {
      await rm(projectDir, { recursive: true, force: true });
      await rm(root, { recursive: true, force: true });
    }
  });

  it('installs a blob skill into a subagent skills directory', async () => {
    const projectDir = await makeEveProject();
    await addEveSubagent(projectDir, 'research');

    try {
      const result = await installBlobSkillForAgent(
        {
          installName: 'blob-subagent',
          files: [
            {
              path: 'SKILL.md',
              contents: '---\nname: blob-subagent\ndescription: Blob subagent\n---\n# Blob\n',
            },
          ],
        },
        'eve',
        { cwd: projectDir, mode: 'copy', global: false, eveSubagent: 'research' }
      );

      expect(result.success).toBe(true);
      expect(result.path).toBe(join(projectDir, 'agent/subagents/research/skills/blob-subagent'));
    } finally {
      await rm(projectDir, { recursive: true, force: true });
    }
  });

  it('reports skills as installed per subagent via isSkillInstalled', async () => {
    const projectDir = await makeEveProject();
    await addEveSubagent(projectDir, 'research');
    const { root, skillDir } = await makeSourceSkill('present');

    try {
      await installSkillForAgent(
        { name: 'present', description: 'present skill', path: skillDir },
        'eve',
        { cwd: projectDir, mode: 'copy', global: false, eveSubagent: 'research' }
      );

      await expect(
        isSkillInstalled('present', 'eve', { cwd: projectDir, eveSubagent: 'research' })
      ).resolves.toBe(true);
      // Not installed at the root agent.
      await expect(isSkillInstalled('present', 'eve', { cwd: projectDir })).resolves.toBe(false);
    } finally {
      await rm(projectDir, { recursive: true, force: true });
      await rm(root, { recursive: true, force: true });
    }
  });

  it('scans subagent directories when listing installed skills', async () => {
    const previousCwd = process.cwd();
    const projectDir = await makeEveProject();
    await addEveSubagent(projectDir, 'research');

    // Place a packaged skill directly in the subagent skills dir.
    const subagentSkillDir = join(getEveSubagentSkillsDir('research', projectDir), 'listed-skill');
    await mkdir(subagentSkillDir, { recursive: true });
    await writeFile(
      join(subagentSkillDir, 'SKILL.md'),
      '---\nname: listed-skill\ndescription: Listed skill\n---\n# Listed\n',
      'utf-8'
    );

    try {
      process.chdir(projectDir);
      const listed = await listInstalledSkills({ cwd: projectDir, global: false });
      const names = listed.map((s) => s.name);
      expect(names).toContain('listed-skill');
    } finally {
      process.chdir(previousCwd);
      await rm(projectDir, { recursive: true, force: true });
    }
  });
  it('keeps name/version/metadata when writing the universal eve copy', async () => {
    const projectDir = await makeEveProject();
    const { root, skillDir } = await makeSourceSkill('full-skill');

    try {
      const result = await installSkillForAgent(
        { name: 'full-skill', description: 'full-skill skill', path: skillDir },
        'eve',
        { cwd: projectDir, mode: 'copy', global: false }
      );

      expect(result.success).toBe(true);

      const installed = await readFile(
        join(projectDir, 'agent/skills/full-skill/SKILL.md'),
        'utf-8'
      );
      expect(installed).toContain('name: full-skill');
      expect(installed).toContain('description:');

      const prevCwd = process.cwd();
      process.chdir(projectDir);
      try {
        const listed = await listInstalledSkills({ cwd: projectDir, global: false });
        expect(listed.map((s) => s.name)).toContain('full-skill');
      } finally {
        process.chdir(prevCwd);
      }
    } finally {
      await rm(projectDir, { recursive: true, force: true });
      await rm(root, { recursive: true, force: true });
    }
  });
});

import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'fs';
import { homedir, tmpdir } from 'os';
import { join } from 'path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { agents, isPositAssistantInstalled } from '../src/agents.ts';
import { findSkillMdPaths } from '../src/blob.ts';
import { discoverSkills } from '../src/skills.ts';

const skillFile = (name: string) => `---
name: ${name}
description: ${name} test skill
---

# ${name}
`;

describe('Posit Assistant agent support', () => {
  let testDir: string;

  beforeEach(() => {
    testDir = mkdtempSync(join(tmpdir(), 'skills-posit-assistant-'));
  });

  afterEach(() => {
    rmSync(testDir, { recursive: true, force: true });
  });

  it('uses the documented project and global skill directories', () => {
    const agent = agents['posit-assistant'];

    expect(agent.name).toBe('posit-assistant');
    expect(agent.displayName).toBe('Posit Assistant');
    expect(agent.skillsDir).toBe('.posit/assistant/skills');
    expect(agent.globalSkillsDir).toBe(join(homedir(), '.posit', 'assistant', 'skills'));
  });

  it('detects Posit Assistant from its config directory', () => {
    const home = '/tmp/home';
    const exists = (path: string) => path === join(home, '.posit/assistant');

    expect(isPositAssistantInstalled(home, exists)).toBe(true);
  });

  it('detects Posit Assistant from the legacy config directory', () => {
    const home = '/tmp/home';
    const exists = (path: string) => path === join(home, '.positai');

    expect(isPositAssistantInstalled(home, exists)).toBe(true);
  });

  it('returns false when no known Posit Assistant path exists', () => {
    expect(isPositAssistantInstalled('/tmp/home', () => false)).toBe(false);
  });

  it('discovers project skills from .posit/assistant/skills alongside standard skills', async () => {
    const positSkillDir = join(testDir, '.posit', 'assistant', 'skills', 'posit-skill');
    const standardSkillDir = join(testDir, 'skills', 'standard-skill');
    mkdirSync(positSkillDir, { recursive: true });
    mkdirSync(standardSkillDir, { recursive: true });
    writeFileSync(join(positSkillDir, 'SKILL.md'), skillFile('posit-skill'));
    writeFileSync(join(standardSkillDir, 'SKILL.md'), skillFile('standard-skill'));

    const discovered = await discoverSkills(testDir);

    expect(discovered.map((skill) => skill.name).sort()).toEqual(['posit-skill', 'standard-skill']);
  });

  it('discovers .posit/assistant/skills through the GitHub tree fast path', () => {
    const discovered = findSkillMdPaths({
      sha: 'root-sha',
      branch: 'main',
      tree: [
        {
          path: '.claude/skills/standard-skill/SKILL.md',
          type: 'blob',
          sha: 'standard-sha',
        },
        {
          path: '.posit/assistant/skills/posit-skill/SKILL.md',
          type: 'blob',
          sha: 'posit-sha',
        },
      ],
    });

    expect(discovered).toContain('.posit/assistant/skills/posit-skill/SKILL.md');
  });
});

